INSERT INTO nigeria_legal_sources (source_code,title,instrument_type,issuing_body,source_url,publication_or_commencement_date,authority_level,reliability_score,verification_status,scope,notes) VALUES ('NG-LUA-1978','Land Use Act','Act','Federal Republic of Nigeria','https://lawsofnigeria.placng.org/view2.php?sn=228','1978-03-29','Official text repository',97,'Verified','Nigeria','Confirm current state-level practice and current legal position before reliance.');
INSERT INTO nigeria_legal_sources (source_code,title,instrument_type,issuing_body,source_url,publication_or_commencement_date,authority_level,reliability_score,verification_status,scope,notes) VALUES ('NG-MMA-2007','Nigerian Minerals and Mining Act 2007','Act','Federal Ministry of Mines and Steel Development','https://minesandsteel.gov.ng/wp-content/uploads/2023/03/Nigerian-Minerals-Mining-Act-2007.pdf','2007-03-29','Official government publication',99,'Verified','Nigeria','Mineral ownership and title framework.');
INSERT INTO nigeria_legal_sources (source_code,title,instrument_type,issuing_body,source_url,publication_or_commencement_date,authority_level,reliability_score,verification_status,scope,notes) VALUES ('NG-EIA-1992','Environmental Impact Assessment Act','Act','Federal Republic of Nigeria / NESREA repository','https://nesrea.gov.ng/wp-content/uploads/2025/09/EIA-ACT.pdf','1992-12-10','Official government repository',98,'Verified','Nigeria','Prior environmental consideration and EIA framework.');
INSERT INTO nigeria_legal_sources (source_code,title,instrument_type,issuing_body,source_url,publication_or_commencement_date,authority_level,reliability_score,verification_status,scope,notes) VALUES ('NG-NDP-2023','Nigeria Data Protection Act 2023','Act','Nigeria Data Protection Commission','https://www.ndpc.gov.ng/ndp-act-2023/','2023-06-12','Official regulator',99,'Verified','Nigeria','Personal-data governance and privacy rights.');
INSERT INTO nigeria_legal_rules (source_id,rule_code,domain_code,title,statement,legal_force,mandatory,applicability,confidence_score,effective_from,evidence_required,competent_authority,indigenous_or_community_relevance,investment_relevance) SELECT id,'NG-LAND-001','LAND_TENURE','State land administration and occupancy framework','Land within each State is vested in the Governor subject to the Land Use Act and administered for the use and common benefit of Nigerians.','Statute',true,'Nigeria land diligence',98,'1978-03-29','Title or occupancy instrument; allocation evidence; survey and location evidence','State land administration authority','High: statutory administration must not be treated as proof that no customary or community interests exist.','Critical' FROM nigeria_legal_sources WHERE source_code='NG-LUA-1978';
INSERT INTO nigeria_legal_rules (source_id,rule_code,domain_code,title,statement,legal_force,mandatory,applicability,confidence_score,effective_from,evidence_required,competent_authority,indigenous_or_community_relevance,investment_relevance) SELECT id,'NG-LAND-002','LAND_TENURE','Urban and non-urban administration must be distinguished','The Land Use Act distinguishes control and management of urban land from other land and assigns relevant functions accordingly.','Statute',true,'Nigeria land diligence',97,'1978-03-29','Jurisdiction classification and applicable allocation records','State land authority / Local Government as applicable','High: location and local context require separate investigation.','High' FROM nigeria_legal_sources WHERE source_code='NG-LUA-1978';
INSERT INTO nigeria_legal_rules (source_id,rule_code,domain_code,title,statement,legal_force,mandatory,applicability,confidence_score,effective_from,evidence_required,competent_authority,indigenous_or_community_relevance,investment_relevance) SELECT id,'NG-MIN-001','MINERAL_RIGHTS','Mineral resources are federally controlled','Property in and control of mineral resources in Nigeria is vested in the Government of the Federation and mineral exploration and exploitation are regulated by the Act.','Statute',true,'Mineral-bearing assets',99,'2007-03-29','Mineral title; cadastral evidence; licence or lease records','Mining Cadastre Office / Ministry of Mines and Steel Development','High: surface land and community interests must be distinguished from mineral title.','Critical' FROM nigeria_legal_sources WHERE source_code='NG-MMA-2007';
INSERT INTO nigeria_legal_rules (source_id,rule_code,domain_code,title,statement,legal_force,mandatory,applicability,confidence_score,effective_from,evidence_required,competent_authority,indigenous_or_community_relevance,investment_relevance) SELECT id,'NG-MIN-002','MINERAL_RIGHTS','No mineral exploration or exploitation without lawful authority','Mineral exploration or exploitation requires authority under the Nigerian Minerals and Mining Act.','Statute',true,'Mining and mineral assets',99,'2007-03-29','Valid mineral title and cadastral confirmation','Mining Cadastre Office / Ministry','High: community and affected-land issues remain separate diligence domains.','Critical' FROM nigeria_legal_sources WHERE source_code='NG-MMA-2007';
INSERT INTO nigeria_legal_rules (source_id,rule_code,domain_code,title,statement,legal_force,mandatory,applicability,confidence_score,effective_from,evidence_required,competent_authority,indigenous_or_community_relevance,investment_relevance) SELECT id,'NG-ENV-001','ENVIRONMENTAL','Prior environmental consideration for qualifying projects','Public or private projects must consider environmental effects at an early stage, and qualifying projects may require environmental impact assessment.','Statute',true,'Qualifying projects',98,'1992-12-10','Project classification and EIA screening or approval evidence where applicable','Competent environmental authority','High: environmental and community impacts should be surfaced before transaction clearance.','Critical' FROM nigeria_legal_sources WHERE source_code='NG-EIA-1992';
INSERT INTO nigeria_legal_rules (source_id,rule_code,domain_code,title,statement,legal_force,mandatory,applicability,confidence_score,effective_from,evidence_required,competent_authority,indigenous_or_community_relevance,investment_relevance) SELECT id,'NG-DATA-001','DATA_PROTECTION','Personal-data processing must be lawful and accountable','The Nigeria Data Protection Act 2023 provides the framework for protecting data-subject rights and regulating personal-data processing.','Statute',true,'Platform processing of personal data',99,'2023-06-12','Lawful processing basis; privacy notice; access controls; retention controls; breach process','Nigeria Data Protection Commission','High where community or individual records contain personal data.','High' FROM nigeria_legal_sources WHERE source_code='NG-NDP-2023';
INSERT INTO nigeria_rights_domains (domain_code,domain_name,institutional_position,primary_authority,source_rule_codes) VALUES ('LAND_TENURE','Land title, tenure and occupancy','Verify location-specific title and occupancy evidence separately from community/customary claims.','State land administration authority',ARRAY['NG-LAND-001','NG-LAND-002']);
INSERT INTO nigeria_rights_domains (domain_code,domain_name,institutional_position,primary_authority,source_rule_codes) VALUES ('CUSTOMARY_COMMUNITY','Customary and community interests','Maintain a dedicated diligence domain; absence of a platform record is never proof that community interests do not exist.','Relevant State/local/traditional/community institutions as legally applicable',ARRAY['NG-LAND-001','NG-LAND-002']);
INSERT INTO nigeria_rights_domains (domain_code,domain_name,institutional_position,primary_authority,source_rule_codes) VALUES ('MINERAL_RIGHTS','Mineral exploration and exploitation rights','Separate federal mineral-title diligence from surface land and occupancy rights.','Mining Cadastre Office / Ministry of Mines and Steel Development',ARRAY['NG-MIN-001','NG-MIN-002']);
INSERT INTO nigeria_rights_domains (domain_code,domain_name,institutional_position,primary_authority,source_rule_codes) VALUES ('ENVIRONMENTAL','Environmental assessment and approvals','Environmental status is an independent readiness gate for qualifying projects.','Competent environmental authority',ARRAY['NG-ENV-001']);
INSERT INTO nigeria_rights_domains (domain_code,domain_name,institutional_position,primary_authority,source_rule_codes) VALUES ('DATA_PROTECTION','Personal-data and privacy rights','Public verification must minimize disclosure and keep sensitive personal data within controlled institutional access.','Nigeria Data Protection Commission',ARRAY['NG-DATA-001']);